@extends('layout') @section('title','Products') @section('content') @include('admin.nav')<h1>Products</h1><div class="panel"><h2 id="form-title">Add product</h2><form method="post" action="{{ route('admin.products.save') }}" enctype="multipart/form-data">@csrf<input type="hidden" name="id" id="product-id"><label>Category</label><select name="category_id" id="product-category" required><option value="">Select category</option>@foreach($categories as $category)<option value="{{ $category->id }}">{{ $category->name }}</option>@endforeach</select><label>Name</label><input name="name" id="product-name" required maxlength="150"><label>Description</label><textarea name="description" id="product-description"></textarea><label>Price (₹)</label><input type="number" name="price" id="product-price" min="0" step="0.01" required><label>Image (JPG, PNG or WebP; max 4 MB)</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><label>Sort order</label><input type="number" name="sort_order" id="product-sort" min="0" value="0"><p><label><input type="checkbox" name="is_available" id="product-available" checked> Available</label></p><button type="submit">Save product</button> <button type="button" onclick="location.reload()">Clear</button></form></div><div class="panel table-wrap"><table><thead><tr><th>Image</th><th>Product</th><th>Category</th><th>Price</th><th>Available</th><th>Actions</th></tr></thead><tbody>@foreach($products as $product)<tr><td>@if($product->image_path)<img width="65" height="50" style="object-fit:cover" src="{{ asset('storage/'.$product->image_path) }}" alt="">@endif</td><td>{{ $product->name }}</td><td>{{ $product->category->name }}</td><td>₹{{ number_format($product->price,2) }}</td><td>{{ $product->is_available?'Yes':'No' }}</td><td class="actions"><button type="button" onclick='editProduct(@json($product))'>Edit</button><form method="post" action="{{ route('admin.products.delete',$product) }}" onsubmit="return confirm('Delete product?')">@csrf @method('DELETE')<button type="submit">Delete</button></form></td></tr>@endforeach</tbody></table></div><script>function editProduct(p){document.querySelector('#form-title').textContent='Edit product';document.querySelector('#product-id').value=p.id;document.querySelector('#product-category').value=p.category_id;document.querySelector('#product-name').value=p.name;document.querySelector('#product-description').value=p.description||'';document.querySelector('#product-price').value=p.price;document.querySelector('#product-sort').value=p.sort_order;document.querySelector('#product-available').checked=!!p.is_available;scrollTo(0,0)}</script>@endsection
